import { test, expect } from '@playwright/test';

test.describe('Home Page Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should navigate to home page by clicking the logo', async ({ page }) => {
    await page.getByRole('img', { name: 'Logo' }).click(); // Replace 'Logo' with the actual alt text of the logo
    await expect(page).toHaveURL('https://example.com/home'); // Replace with the actual home page URL
  });

  test('should display the home page content after navigation', async ({ page }) => {
    await page.getByRole('img', { name: 'Logo' }).click(); // Replace 'Logo' with the actual alt text of the logo
    await expect(page.getByText('Welcome to the Home Page')).toBeVisible(); // Replace with actual text on the home page
  });
});
